using MediatR; using JTradeERP.Application.Common.Persistence; namespace JTradeERP.Application.Features.MasterData.UnitsOfMeasure.GetUnitsOfMeasure; public sealed class GetUnitsOfMeasureHandler(IApplicationDbContext db):IRequestHandler<GetUnitsOfMeasureQuery,IReadOnlyList<GetUnitsOfMeasureResponse>>{public Task<IReadOnlyList<GetUnitsOfMeasureResponse>> Handle(GetUnitsOfMeasureQuery r,CancellationToken ct)=>Task.FromResult<IReadOnlyList<GetUnitsOfMeasureResponse>>(db.UnitsOfMeasure.OrderBy(x=>x.Code).Select(e=>new GetUnitsOfMeasureResponse(e.Id,e.Code,e.Name)).ToList());}
